CREATE OR REPLACE FUNCTION public.onderneming_hoofdkaart(_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE pad AS (SELECT id,samengevoegd_naar,ARRAY[id] bezocht FROM public.ondernemingen WHERE id=_id UNION ALL SELECT o.id,o.samengevoegd_naar,p.bezocht||o.id FROM pad p JOIN public.ondernemingen o ON o.id=p.samengevoegd_naar WHERE NOT o.id=ANY(p.bezocht)) SELECT id FROM pad ORDER BY cardinality(bezocht) DESC LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.onderneming_hoofdkaart(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.onderneming_hoofdkaart(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.tel_aanvraag_cohort(_vanaf date DEFAULT date '2026-10-06') RETURNS TABLE(sleutel uuid,dag date,kvk text,statusgroep text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 WITH bron AS (
 SELECT l.id,l.id lead_id,nullif(regexp_replace(coalesce(l.kvk_nummer,''),'[^0-9]','','g'),'') kvk,(l.created_at AT TIME ZONE 'Europe/Amsterdam')::date dag,l.status::text status FROM public.leads l WHERE l.type='verzekering_aanvraag' AND NOT coalesce(l.is_test,false) AND (l.created_at AT TIME ZONE 'Europe/Amsterdam')::date BETWEEN _vanaf AND date '2026-12-31'
 UNION ALL SELECT coalesce(b.lead_id,b.id),l.id,nullif(regexp_replace(coalesce(l.kvk_nummer,b.kvk_nummer,''),'[^0-9]','','g'),''),(b.aangemeld_op AT TIME ZONE 'Europe/Amsterdam')::date,coalesce(l.status::text,b.status) FROM public.bav_aanmeldingen b LEFT JOIN public.leads l ON l.id=b.lead_id WHERE NOT coalesce(b.is_test,false) AND NOT coalesce(l.is_test,false) AND (l.id IS NULL OR l.type='verzekering_aanvraag') AND (b.aangemeld_op AT TIME ZONE 'Europe/Amsterdam')::date BETWEEN _vanaf AND date '2026-12-31'
 ), gegroepeerd AS (SELECT CASE WHEN kvk ~ '^[0-9]{8}$' THEN kvk ELSE id::text END groep,(array_agg(id ORDER BY (lead_id IS NULL),dag,id))[1] sleutel,min(dag) dag,max(kvk) kvk,bool_or(status='actief') actief,bool_or(status='in_behandeling') behandeling,bool_or(status IN ('nieuw','nieuw_te_beoordelen')) beoordeling FROM bron GROUP BY 1)
 SELECT g.sleutel,g.dag,g.kvk,CASE WHEN g.actief OR EXISTS(SELECT 1 FROM public.ondernemingen o JOIN public.klant_contracten c ON c.onderneming_id=public.onderneming_hoofdkaart(o.id) JOIN public.ondernemingen hoofd ON hoofd.id=c.onderneming_id WHERE o.kvk=g.kvk AND g.kvk ~ '^[0-9]{8}$' AND NOT coalesce(o.is_test,false) AND NOT coalesce(hoofd.is_test,false) AND c.product='bav_avb' AND c.status<>'vervangen' AND NOT coalesce(c.is_test,false)) THEN 'klant' WHEN g.behandeling THEN 'in_behandeling' WHEN g.beoordeling THEN 'te_beoordelen' ELSE 'overig' END FROM gegroepeerd g $$;
REVOKE ALL ON FUNCTION public.tel_aanvraag_cohort(date) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.tel_aanvraag_cohort(date) TO service_role;
CREATE OR REPLACE FUNCTION public.tel_aanvragen_doel_rijen(_vanaf date DEFAULT date '2026-10-06') RETURNS TABLE(sleutel uuid,dag date) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.sleutel,c.dag FROM public.tel_aanvraag_cohort(_vanaf) c $$;
CREATE OR REPLACE FUNCTION public.controleer_aanvraag_opbouw(_a jsonb,_doel bigint) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ BEGIN IF _a IS NULL OR (_a->>'totaal') IS NULL OR (_a->>'klant') IS NULL OR (_a->>'in_behandeling') IS NULL OR (_a->>'te_beoordelen') IS NULL OR (_a->>'overig') IS NULL OR _doel IS NULL OR (_a->>'totaal')::bigint<>_doel OR (_a->>'totaal')::bigint<>(_a->>'klant')::bigint+(_a->>'in_behandeling')::bigint+(_a->>'te_beoordelen')::bigint+(_a->>'overig')::bigint THEN RAISE EXCEPTION 'Aanvraagopbouw sluit niet aan op het doelaantal' USING ERRCODE='23514'; END IF; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.controleer_aanvraag_opbouw(jsonb,bigint) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.controleer_aanvraag_opbouw(jsonb,bigint) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.tel_dashboard_opbouw() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE a jsonb; l jsonb; BEGIN SELECT jsonb_build_object('vanaf','2026-10-06','tot','2026-12-31','totaal',count(*),'klant',count(*) FILTER(WHERE statusgroep='klant'),'in_behandeling',count(*) FILTER(WHERE statusgroep='in_behandeling'),'te_beoordelen',count(*) FILTER(WHERE statusgroep='te_beoordelen'),'overig',count(*) FILTER(WHERE statusgroep='overig')) INTO a FROM public.tel_aanvraag_cohort(date '2026-10-06'); PERFORM public.controleer_aanvraag_opbouw(a,public.tel_aanvragen_doel(date '2026-10-06')); SELECT jsonb_build_object('vanaf',min((created_at AT TIME ZONE 'Europe/Amsterdam')::date),'totaal',count(*),'aanvragen',count(*) FILTER(WHERE type='verzekering_aanvraag'),'contact',count(*) FILTER(WHERE type='contact'),'offerte',count(*) FILTER(WHERE type='offerte-aanvraag')) INTO l FROM public.leads WHERE NOT coalesce(is_test,false); IF (l->>'totaal')::bigint<>(l->>'aanvragen')::bigint+(l->>'contact')::bigint+(l->>'offerte')::bigint THEN RAISE EXCEPTION 'Leadopbouw sluit niet aan op het totaal' USING ERRCODE='23514'; END IF; RETURN jsonb_build_object('aanvragen_opbouw',a,'leads_opbouw',l,'telling_controle',true); END $$;
REVOKE ALL ON FUNCTION public.tel_dashboard_opbouw() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.tel_dashboard_opbouw() TO service_role;
CREATE OR REPLACE FUNCTION public.tel_instroom_opbouw(_vanaf date DEFAULT date '2026-10-01',_toon_test boolean DEFAULT false) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH k AS (SELECT c.id,c.begin_datum,c.bron,(SELECT min((l.created_at AT TIME ZONE 'Europe/Amsterdam')::date) FROM public.leads l JOIN public.ondernemingen x ON x.kvk=l.kvk_nummer AND public.onderneming_hoofdkaart(x.id)=public.onderneming_hoofdkaart(o.id) WHERE l.type='verzekering_aanvraag' AND (_toon_test OR NOT coalesce(l.is_test,false))) aanvraag_dag FROM public.klant_contracten c JOIN public.ondernemingen o ON o.id=c.onderneming_id WHERE c.product IN ('bav_avb','cyber_clear') AND c.status<>'vervangen' AND (_toon_test OR (NOT coalesce(c.is_test,false) AND NOT coalesce(o.is_test,false))) AND c.begin_datum>=_vanaf), n AS (SELECT *,begin_datum<=(now() AT TIME ZONE 'Europe/Amsterdam')::date ingegaan FROM k) SELECT jsonb_build_object('via_aanvraag',count(*) FILTER(WHERE ingegaan AND aanvraag_dag IS NOT NULL),'voor_6_okt',count(*) FILTER(WHERE ingegaan AND aanvraag_dag<date '2026-10-06'),'afas_overzetting',count(*) FILTER(WHERE ingegaan AND aanvraag_dag IS NULL AND bron='afas_20261001'),'overig',count(*) FILTER(WHERE ingegaan AND aanvraag_dag IS NULL AND bron IS DISTINCT FROM 'afas_20261001'),'nog_in_te_gaan',count(*) FILTER(WHERE NOT ingegaan)) FROM n $$;
REVOKE ALL ON FUNCTION public.tel_instroom_opbouw(date,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.tel_instroom_opbouw(date,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.synchroniseer_aanvraag_contract(_onderneming uuid,_tijd timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; tijd timestamptz; BEGIN FOR r IN SELECT DISTINCT l.id,l.geactiveerd_op,l.is_test FROM public.leads l JOIN public.ondernemingen o ON o.kvk=l.kvk_nummer WHERE public.onderneming_hoofdkaart(o.id)=public.onderneming_hoofdkaart(_onderneming) AND l.type='verzekering_aanvraag' AND l.kvk_nummer ~ '^[0-9]{8}$' AND NOT coalesce(l.is_test,false) AND NOT coalesce(o.is_test,false) AND l.status IN ('nieuw','nieuw_te_beoordelen','in_behandeling','afspraak_gepland','offerte_verstuurd') AND EXISTS(SELECT 1 FROM public.klant_contracten c JOIN public.ondernemingen h ON h.id=c.onderneming_id WHERE public.onderneming_hoofdkaart(c.onderneming_id)=public.onderneming_hoofdkaart(_onderneming) AND c.product='bav_avb' AND c.status IN ('actief','loopt_af','einddatum_controle') AND NOT coalesce(c.is_test,false) AND NOT coalesce(h.is_test,false)) LOOP tijd:=coalesce(r.geactiveerd_op,_tijd); UPDATE public.leads SET status='actief',converted_at=tijd WHERE id=r.id; INSERT INTO public.activiteiten_log(actie_type,omschrijving,lead_id,is_test,uitgevoerd_door) VALUES('lead_contract_gesynchroniseerd','Aanvraag op actief gezet bij contractactivatie of samenvoeging van klantkaarten.',r.id,false,auth.uid()); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.synchroniseer_aanvraag_contract(uuid,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.synchroniseer_aanvraag_contract(uuid,timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.aanvraag_contract_lifecycle() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='klant_contracten' THEN IF NEW.product='bav_avb' AND NEW.status IN ('actief','loopt_af','einddatum_controle') AND NOT coalesce(NEW.is_test,false) AND (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status OR NEW.onderneming_id IS DISTINCT FROM OLD.onderneming_id) THEN PERFORM public.synchroniseer_aanvraag_contract(NEW.onderneming_id,NEW.created_at); END IF; ELSE IF NEW.samengevoegd_naar IS NOT NULL AND NEW.samengevoegd_naar IS DISTINCT FROM OLD.samengevoegd_naar AND NOT coalesce(NEW.is_test,false) THEN PERFORM public.synchroniseer_aanvraag_contract(NEW.samengevoegd_naar,(SELECT min(created_at) FROM public.klant_contracten WHERE onderneming_id=public.onderneming_hoofdkaart(NEW.samengevoegd_naar) AND product='bav_avb' AND status IN ('actief','loopt_af','einddatum_controle') AND NOT coalesce(is_test,false))); END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.aanvraag_contract_lifecycle() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER aanvraag_contract_lifecycle AFTER INSERT OR UPDATE OF status,onderneming_id ON public.klant_contracten FOR EACH ROW EXECUTE FUNCTION public.aanvraag_contract_lifecycle();
CREATE TRIGGER aanvraag_samenvoeg_lifecycle AFTER UPDATE OF samengevoegd_naar ON public.ondernemingen FOR EACH ROW EXECUTE FUNCTION public.aanvraag_contract_lifecycle();
CREATE OR REPLACE FUNCTION public.aanvraag_activatie_status() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.type='verzekering_aanvraag' AND NOT coalesce(NEW.is_test,false) AND NEW.geactiveerd_op IS NOT NULL AND NEW.geactiveerd_op IS DISTINCT FROM OLD.geactiveerd_op AND NEW.status IN ('nieuw','nieuw_te_beoordelen','in_behandeling','actief','klant') AND EXISTS(SELECT 1 FROM public.ondernemingen o JOIN public.klant_contracten c ON c.onderneming_id=public.onderneming_hoofdkaart(o.id) WHERE o.kvk=NEW.kvk_nummer AND NOT coalesce(o.is_test,false) AND c.product='bav_avb' AND c.status IN ('actief','loopt_af','einddatum_controle') AND NOT coalesce(c.is_test,false)) THEN NEW.status:='actief'; NEW.converted_at:=coalesce(NEW.converted_at,NEW.geactiveerd_op); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.aanvraag_activatie_status() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER aanvraag_activatie_status BEFORE UPDATE OF geactiveerd_op ON public.leads FOR EACH ROW EXECUTE FUNCTION public.aanvraag_activatie_status();
DO $wire$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.tel_netto_groei(date,boolean)'::regprocedure); d:=replace(d,'  RETURN res;', E'  res := res || jsonb_build_object(''instroom_opbouw'',public.tel_instroom_opbouw(_vanaf,_toon_test));\n  IF (res#>>''{cumulatief,instroom}'')::bigint <> (res#>>''{instroom_opbouw,via_aanvraag}'')::bigint+(res#>>''{instroom_opbouw,afas_overzetting}'')::bigint+(res#>>''{instroom_opbouw,overig}'')::bigint THEN RAISE EXCEPTION ''Instroomopbouw sluit niet aan''; END IF;\n  RETURN res;'); IF position('instroom_opbouw' IN d)=0 THEN RAISE EXCEPTION 'netto groei wiring failed'; END IF; EXECUTE d;
 d:=pg_get_functiondef('public.dashboard_tellers(boolean)'::regprocedure); d:=replace(d,'  RETURN r;',E'  r := r || public.tel_dashboard_opbouw();\n  PERFORM public.controleer_aanvraag_opbouw(r->''aanvragen_opbouw'',(r->>''aanvragen_doel'')::bigint);\n  RETURN r;'); IF position('tel_dashboard_opbouw' IN d)=0 THEN RAISE EXCEPTION 'dashboard wiring failed'; END IF; EXECUTE d;
 d:=pg_get_functiondef('public.scherm_data()'::regprocedure); d:=replace(d,'  RETURN res;',E'  res := res || public.tel_dashboard_opbouw();\n  PERFORM public.controleer_aanvraag_opbouw(res->''aanvragen_opbouw'',(res#>>''{doel,totaal}'')::bigint);\n  RETURN res;'); IF position('tel_dashboard_opbouw' IN d)=0 THEN RAISE EXCEPTION 'screen wiring failed'; END IF; EXECUTE d;
END $wire$;